Certainly! Below is a simple Go program that reads a Go source file containing a struct definition, parses it into an Avro schema using `avro-go` library, and writes the resulting Avro schema to a file.

### Dependencies

First, ensure you have the necessary dependencies installed:

```sh
go get github.com/avroschema/go-avro/schema
```

### Example Usage

To use this program, simply run it with the path to your Go source file as an argument. For example:

```sh
go run main.go /path/to/your/file.go MyStruct
```

This will create a file called `MyStruct.avsc`.

### Full Program

Here's the full Go program:

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"

	"github.com/avroschema/go-avro/schema"
)

func readGoFile(filePath string) (*schema.Type, error) {
	f, err := os.Open(filePath)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	var result *schema.Type

	for scanner.Scan() {
		line := scanner.Text()
		switch line {
		case "type":
			if !scanner.Scan() || scanner.Text() != "{" {
				return nil, fmt.Errorf("expected '{' after 'type'")
			}
		case "}":
			break
		default:
			result = append(result, &schema.Field{
				Name:  scanner.Text(),
				Type:  schema.Parse(scanner.Text()),
				Required: true,
			})
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, err
	}

	return result, nil
}

func main() {
	filePath := os.Args[1]
	structName := os.Args[2]

	outputFilePath := filepath.Join(filepath.Dir(filePath), fmt.Sprintf("%s.avsc", structName))

	if err := filepath.WalkDir(
		filePath,
		func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}

			if d.IsDir() {
				return nil
			}

			if strings.HasSuffix(path, ".go") && strings.Contains(d.Name(), structName) {
				fmt.Printf("Parsing %s...\n", path)
				typeDef, err := readGoFile(path)
				if err != nil {
					fmt.Printf("Error reading %s: %v\n", path, err)
					continue
				}

				schemaBytes, _ := schema.Encode(typeDef)
				err = os.WriteFile(outputFilePath, schemaBytes, 0644)
				if err != nil {
					fmt.Printf("Error writing %s: %v\n", outputFilePath, err)
					return nil
				}

				fmt.Printf("Generated %s successfully.\n", outputFilePath)
				return nil
			}
			return nil
		},
	); err != nil {
		fmt.Printf("Error walking directory: %v\n", err)
		os.Exit(1)
	}
}
```

### Explanation

1. **Dependencies**: The program uses the `github.com/avroschema/go-avro/schema` package to handle Avro schemas.
2. **Reading the Go File**:
   - Opens the specified Go file.
   - Parses each line to extract field names and types.
3. **Generating the Schema**:
   - Checks if the line starts with `"type"` or ends with `"{"`.
   - Constructs a type definition for fields.
4. **Writing the Schema**:
   - Uses the `schema.Encode` function to convert the type definition into Avro schema bytes.

